  const remote = deps.remote;
  const schema = deps.schema;

  if (!storage) {
    throw createClientError(
      "DFQL_INVALID",
      "Invalid cloneUp: storage is required",
      { path: "storage" },
    );
  }

  if (!remote) {
    throw createClientError(
      "DFQL_INVALID",
      "Invalid cloneUp: sync.remote is required",
      { path: "sync.remote" },
    );
  }

  if (!schema) {
    throw createClientError(
      "INTERNAL",
      "Invalid cloneUp: schema is not available",
      { path: "schema" },
    );
