      const mutationId = `${prefix}:rec:${resourceName}:${record.id}:${hash}`;

      mutations.push({
        resource: resourceName,
        version: resourceSchema.version,
        operation: recordOperation,
        id: record.id,
        record: filteredRecord,
        clientId: deps.clientId,
        mutationId,
