AAAA,EACF;AACA,EAAA,OAAO;AAAA,IACL,IAAA,EAAM,UAAA;AAAA,IACN,OAAA,EAAS,OAAOA,IAAG,CAAA;AAAA,IACnB,SAAS,EAAE,IAAA,EAAM,WAAW,UAAU,CAAA,CAAA,EAAI,QAAQ,CAAA,CAAA;AAAG,GACvD;AACF;AASA,eAAsB,aAAA,CACpB,SACA,GAAA,EACA,QAAA,EACA,KACA,OAAA,EACA,OAAA,GAAqB,EAAC,EACQ;AAC9B,EAAA,IAAI,OAAA,GAAU,OAAA;AACd,EAAA,MAAM,QAAA,GAAW,QAAQ,MAAA,CAAO,CAAC,MAAM,CAAA,CAAE,MAAA,CAAO,QAAA,CAAS,GAAG,CAAC,CAAA;AAE7D,EAAA,KAAA,MAAW,UAAU,QAAA,EAAU;AAC7B,IAAA,MAAM,IAAA,GAAO,OAAO,QAAQ,CAAA;AAC5B,IAAA,IAAI,CAAC,IAAA,EAAM;AAEX,IAAA,IAAI;AACF,MAAA,MAAM,SAAS,MAAM,IAAA,CAAK,GAAA,EAAK,GAAG,SAAS,OAAO,CAAA;AAClD,MAAA,IAAI,MAAA,KAAW,QAAW,OAAA,GAAU,MAAA;AAAA,IACtC,SAASA,IAAAA,EAAK;AACZ,MAAA,OAAO,EAAE,EAAA,EAAI,KAAA,EAAO,KAAA,EAAO,SAAA,CAAUA,IAAAA,EAAK,MAAA,CAAO,IAAA,EAAM,MAAA,CAAO,QAAQ,CAAC,CAAA,EAAE;AAAA,IAC3E;AAAA,EACF;AAEA,EAAA,OAAO,EAAE,EAAA,EAAI,IAAA,EAAM,KAAA,EAAO,OAAA,EAAQ;AACpC;AAQA,eAAsB,YAAA,CACpB,SACA,GAAA,EACA,QAAA,EACA,KACA,OAAA,EACA,MAAA,EACA,OAAA,GAAqB,EAAC,EACJ;AAClB,EAAA,MAAM,QAAA,GAAW,QAAQ,MAAA,CAAO,CAAC,MAAM,CAAA,CAAE,MAAA,CAAO,QAAA,CAAS,GAAG,CAAC,CAAA;AAC7D,EAAA,IAAI,aAAA,GAAgB,MAAA;AAEpB,EAAA,KAAA,MAAW,UAAU,QAAA,EAAU;AAC7B,IAAA,MAAM,IAAA,GAAO,OAAO,QAAQ,CAAA;AAC5B,IAAA,IAAI,CAAC,IAAA,EAAM;AAEX,IAAA,IAAI;AACF,MAAA,MAAM,aAAa,MAAM,IAAA,CAAK,KAAK,GAAG,OAAA,EAAS,SAAS,aAAa,CAAA;AACrE,MAAA,IAAI,eAAe,KAAA,CAAA,EAAW;AAC5B,QAAA,aAAA,GAAgB,UAAA;AAAA,MAClB;AAAA,IACF,SAASA,IAAAA,EAAK;AACZ,MAAA,OAAA,CAAQ,KAAA,CAAM,UAAU,MAAA,CAAO,IAAI,IAAI,MAAA,CAAO,QAAQ,CAAC,CAAA,OAAA,CAAA,EAAWA,IAAG,CAAA;AAAA,IACvE;AAAA,EACF;AAEA,EAAA,OAAO,aAAA;AACT;;;ACpGO,IAAM,0BAAA,GAA6B;AACnC,IAAM,wBAAA,GAA2B;AACjC,IAAM,6BAAA,GAAgC;AACtC,IAAM,+BAAA,GAAkC;AACxC,IAAM,8BAAA,GAAiC;AACvC,IAAM,uBAAA,GAA0B;AAsBhC,SAAS,8BAAA,CAA+B,KAAA,EAAe,SAAA,GAAY,KAAA,EAAe;AACvF,EAAA,MAAM,GAAA,GAAM,IAAI,GAAA,CAAI,KAAK,CAAA;AACzB,EAAA,MAAM,KAAA,GAAQ,CAAC,WAAA,EAAa,WAAA,EAAa,OAAO,CAAA,CAAE,QAAA,CAAS,IAAI,QAAQ,CAAA;AACvE,EAAA,MAAM,QAAA,GAAW,YAAY,MAAA,GAAS,QAAA;AACtC,EAAA,MAAM,aAAA,GAAgB,YAAY,KAAA,GAAQ,OAAA;AAC1C,EAAA,IAAK,IAAI,QAAA,KAAa,QAAA,IAAY,EAAE,KAAA,IAAS,GAAA,CAAI,aAAa,aAAA,CAAA,IAC5D,GAAA,CAAI,YAAY,GAAA,CAAI,QAAA,IAAY,MAAM,QAAA,CAAS,GAAG,KAAK,KAAA,CAAM,QAAA,CAAS,GAAG,CAAA,EAAG;AAC5E,IAAA,MAAM,IAAI,MAAM,+BAA+B,CAAA;AAAA,EACjD;AACA,EAAA,OAAO,GAAA,CAAI,QAAA,EAAS,CAAE,OAAA,CAAQ,OAAO,EAAE,CAAA;AACzC","file":"index.cjs","sourcesContent":["/**
 * DataFn Schema Types
 */

import type { DatafnError } from "./errors.js";
import type {
  CapabilityEntry,
  SchemaCapabilities,
  ResourceCapabilities,
  SimpleCapability,
} from "./capabilities.js";

export type DatafnSchema = {
  version?: number;
  capabilities?: SchemaCapabilities;
  defaultPermissions?: DatafnDefaultPermissionsPolicy;
  resources: readonly DatafnResourceSchema[];
  relations?: readonly DatafnRelationSchema[];
  relationIntegrity?: DatafnRelationIntegrityMode;
  /** Defaults to true. Set to false to disable row-level namespace isolation. */
  namespaced?: boolean;
};

export type DatafnDefaultPermissionsFieldMode = "allResourceFields";

export type DatafnDefaultPermissionsPolicy =
  | DatafnDefaultPermissionsFieldMode
  | {
      read?: DatafnDefaultPermissionsFieldMode | false;
      write?: DatafnDefaultPermissionsFieldMode | false;
      relationWrites?: "all" | false;
    };

/**
 * Permissions policy shape for server-side authorization enforcement.
 * All field arrays are optional; if omitted, no fields are accessible.
 */
export type DatafnPermissionsPolicy = {
  /**
   * Read policy: controls which fields can be selected and filtered.
   */
  read?: {
    fields: readonly string[];
  };
  /**
   * Write policy: controls which fields can be written via mutations.
   */
  write?: {
    fields: readonly string[];
  };
  /**
   * Optional owner field for owner-scoped resources.
   * When set, additional owner-based authorization checks can be performed.
   */
  ownerField?: string;
};

export type DatafnResourceSchema = {
  name: string;
  version: number;
  idPrefix?: string;
  isRemoteOnly?: boolean;
  /**
   * Resource capabilities.
   * For shareable resources, SPV2 extends shareable config with
   * visibility/membership/scope-related options while preserving legacy fields.
   */
  capabilities?: ResourceCapabilities;
  fields: readonly DatafnFieldSchema[];
  indices?:
    | {
        base?: readonly string[];
        search?: readonly string[];
        vector?: readonly string[];
      }
    | readonly string[];
  defaultPermissions?: false;
  permissions?: DatafnPermissionsPolicy;
};

export type DatafnFieldSchema = {
  name: string;
  type: "string" | "number" | "boolean" | "object" | "array" | "date" | "file" | "json";
  required: boolean;
  nullable?: boolean;
  readonly?: boolean;
  default?: unknown;
  enum?: readonly unknown[];
  min?: number;
  max?: number;
  minLength?: number;
  maxLength?: number;
  pattern?: string;
  unique?: boolean | string;
  encrypt?: boolean;
  volatile?: boolean;
};

export type RelationSimpleCapability = "timestamps" | "audit";

export type DatafnRelationIntegrityMode = "application" | "database";

export type DatafnRelationDeletePolicy =
  | "restrict"
  | "cascade"
  | "setNull"
  | "detach";

export type DatafnRelationDeletePolicies =
  | DatafnRelationDeletePolicy
  | {
      from?: DatafnRelationDeletePolicy;
      to?: DatafnRelationDeletePolicy;
    };

export type DatafnRelationSchema = {
  from: string | readonly string[];
  to: string | readonly string[];
  type: "one-many" | "many-one" | "many-many" | "htree";
  relation?: string;
  inverse?: string;
  cache?: boolean;
  metadata?: readonly {
    name: string;
    type: "string" | "number" | "boolean" | "date" | "object" | "json";
  }[];
  identityMetadata?: readonly string[];
  fkField?: string;
  /** @deprecated Use fkField. Retained for legacy schema compatibility. */
  foreignKey?: string;
  fkResourceField?: string;
  pathField?: string;
  joinTable?: string;
  joinColumns?: { from: string; to: string };
  integrity?: DatafnRelationIntegrityMode;
  onDelete?: DatafnRelationDeletePolicies;
  inheritsInactive?: boolean;
  capabilities?: readonly RelationSimpleCapability[];
};

/**
 * Type-safe schema definition helper.
 * Uses const generic to preserve literal field name types and constrain
 * index entries to only declared field names within each resource.
 */
type DatafnFieldInput = {
  readonly name: string;
  readonly type: DatafnFieldSchema["type"];
  readonly required: boolean;
  readonly [k: string]: unknown;
};

type DatafnIndicesInput<FieldName extends string> =
  | { readonly base?: readonly FieldName[]; readonly search?: readonly FieldName[]; readonly vector?: readonly FieldName[] }
  | readonly FieldName[];

type SchemaCapabilitiesInput = readonly CapabilityEntry[];
type ResourceCapabilitiesInput =
  | SchemaCapabilitiesInput
  | { readonly exclude: readonly SimpleCapability[] };

type DatafnResourceBase = {
  readonly name: string;
  readonly version: number;
  readonly idPrefix?: string;
  readonly isRemoteOnly?: boolean;
  readonly capabilities?: ResourceCapabilitiesInput;
  readonly fields: readonly DatafnFieldInput[];
  readonly indices?: DatafnIndicesInput<string>;
  readonly defaultPermissions?: false;
  readonly permissions?: DatafnPermissionsPolicy;
  readonly [k: string]: unknown;
};

type ValidateResources<R extends readonly DatafnResourceBase[]> = {
  readonly [K in keyof R]: R[K] extends { readonly fields: readonly { readonly name: infer N extends string }[] }
    ? Omit<R[K], "indices"> & { readonly indices?: DatafnIndicesInput<N> }
    : R[K];
};

declare const datafnSchemaLiteral: unique symbol;

export type DatafnDefinedSchema<T> = T & DatafnSchema & {
  readonly [datafnSchemaLiteral]?: T;
};

export type DatafnSchemaLiteral<S> =
  S extends { readonly [datafnSchemaLiteral]?: infer T } ? T : S;

export function defineSchema<
  const T extends {
    readonly capabilities?: SchemaCapabilitiesInput;
    readonly defaultPermissions?: DatafnDefaultPermissionsPolicy;
    readonly resources: readonly DatafnResourceBase[];
    readonly relations?: readonly DatafnRelationSchema[] | DatafnRelationSchema[];
    readonly relationIntegrity?: DatafnRelationIntegrityMode;
    readonly namespaced?: boolean;
  }
>(schema: T & { readonly resources: ValidateResources<T["resources"]> }): DatafnDefinedSchema<T> {
  return schema as unknown as DatafnDefinedSchema<T>;
}

/**
 * Event Types
 */

export interface DatafnEvent {
  type:
    | "mutation_applied"
    | "mutation_rejected"
    | "sync_started"
    | "sync_applied"
    | "sync_failed"
    | "sync_retry"
    | "connectivity_changed"
    | "ws_connected"
    | "ws_disconnected";
  resource?: string;
  ids?: string[];
  mutationId?: string;
  clientId?: string;
  timestampMs: number;
  context?: unknown;
  action?: string;
  fields?: string[];
  // MUT-002: When true, marks mutation as system-initiated
  system?: boolean;
  // TAB-001: When true, marks event as received from another tab (prevents re-broadcast)
  fromRemoteTab?: boolean;
}

export type DatafnEventFilter = Partial<{
  type: DatafnEvent["type"] | Array<DatafnEvent["type"]>;
  resource: string | string[];
  ids: string | string[];
  mutationId: string | string[];
  action: string | string[];
  fields: string | string[];
  contextKeys: string[];
  context: Record<string, unknown>;
}>;

/**
 * Signal Type
 */

export interface DatafnSignal<T> {
  get(): T;
  subscribe(handler: (value: T) => void): () => void;
  readonly loading: boolean;
  readonly error: DatafnError | null;
  readonly refreshing: boolean;
  readonly nextCursor: string | null | undefined;
  dispose(): void;
}

/**
 * Logger interface for structured, pluggable logging.
 */
export interface DatafnLogger {
  info(message: string, context?: Record<string, unknown>): void;
  warn(message: string, context?: Record<string, unknown>): void;
  error(message: string, context?: Record<string, unknown>): void;
  debug(message: string, context?: Record<string, unknown>): void;
}

/**
 * Limits configuration for server-side enforcement.
 */
export type DatafnLimitsConfig = {
  maxLimit?: number;
  maxTransactSteps?: number;
  maxPayloadBytes?: number;
  maxPullLimit?: number;
  maxBatchSize?: number;
  maxCloneRecords?: number;
  idempotencyTtlMs?: number;
  idempotencyMaxEntries?: number;
  maxSelectTokens?: number;
  maxFilterKeysPerLevel?: number;
  maxSortFields?: number;
  maxAggregations?: number;
  maxSearchQueryLength?: number;
  maxLikePatternLength?: number;
  maxIdLength?: number;
  maxFilterDepth?: number;
};

/**
 * WebSocket configuration for connection limits and heartbeat.
 */
export type DatafnWsConfig = {
  maxConnections?: number;
  maxConnectionsPerNamespace?: number;
  heartbeatIntervalMs?: number;
  heartbeatTimeoutMs?: number;
};

/**
 * Plugin Types
 */

export type DatafnHookContext = {
  env: "client" | "server";
  schema: DatafnSchema;
  context?: unknown;
};

export interface DatafnPlugin {
  name: string;
  runsOn: Array<"client" | "server">;
  beforeQuery?: (
    ctx: DatafnHookContext,
    q: unknown,
  ) => Promise<unknown> | unknown;
  beforeSearch?: (
    ctx: DatafnHookContext,
    search: unknown,
  ) => Promise<unknown> | unknown;
  afterQuery?: (
    ctx: DatafnHookContext,
    q: unknown,
    result: unknown,
  ) => Promise<unknown> | unknown;
  beforeMutation?: (
    ctx: DatafnHookContext,
    m: unknown | unknown[],
  ) => Promise<unknown> | unknown;
  afterMutation?: (
    ctx: DatafnHookContext,
    m: unknown | unknown[],
    result: unknown,
  ) => Promise<unknown> | unknown;
  beforeSync?: (
    ctx: DatafnHookContext,
    phase: "seed" | "clone" | "pull" | "push" | "cloneUp" | "reconcile",
    payload: unknown,
  ) => Promise<unknown> | unknown;
  afterSync?: (
    ctx: DatafnHookContext,
    phase: "seed" | "clone" | "pull" | "push" | "cloneUp" | "reconcile",
    payload: unknown,
    result: unknown,
  ) => Promise<unknown> | unknown;
}
","import type { DatafnFieldSchema } from "./types.js";

type DatafnFieldType = DatafnFieldSchema["type"];
type NoFieldOptions = Record<never, never>;

type DatafnFieldMetadataOptions = Partial<
  Pick<DatafnFieldSchema, "readonly" | "unique" | "encrypt" | "volatile">
>;

type DatafnFieldCommonOptions<Value> = DatafnFieldMetadataOptions & {
  required?: boolean;
} & (
    | {
        nullable?: false;
        default?: Value;
      }
    | {
        nullable: true;
        default?: Value | null;
      }
  );

type DatafnEnumOptions<Value> = {
  enum?: readonly Value[];
};

/** A JSON-compatible value accepted by a DataFn JSON field. */
export type DatafnJsonValue =
  | null
  | boolean
  | number
  | string
  | readonly DatafnJsonValue[]
  | { readonly [key: string]: DatafnJsonValue };

/** Named options for a string field. */
export type DatafnStringFieldOptions = DatafnFieldCommonOptions<string> &
  DatafnEnumOptions<string> & {
    minLength?: number;
    maxLength?: number;
    pattern?: string;
  };

/** Named options for a number field. */
export type DatafnNumberFieldOptions = DatafnFieldCommonOptions<number> &
  DatafnEnumOptions<number> & {
    min?: number;
    max?: number;
  };

/** Named options for a boolean field. */
export type DatafnBooleanFieldOptions = DatafnFieldCommonOptions<boolean> &
  DatafnEnumOptions<boolean>;

/** Named options for an object field. */
export type DatafnObjectFieldOptions = DatafnFieldCommonOptions<
  Readonly<Record<string, unknown>>
>;

/** Named options for an array field. */
export type DatafnArrayFieldOptions = DatafnFieldCommonOptions<
  readonly unknown[]
> & {
  min?: number;
  max?: number;
};

/** Named options for a date field. */
export type DatafnDateFieldOptions = DatafnFieldCommonOptions<
  string | number
> & {
  min?: number;
  max?: number;
};

/** Named options for a file-reference field. */
export type DatafnFileFieldOptions = DatafnFieldCommonOptions<string> &
  DatafnEnumOptions<string>;

/** Named options for a JSON field. */
export type DatafnJsonFieldOptions = DatafnFieldCommonOptions<
  Exclude<DatafnJsonValue, null>
>;

/** Maps each public field kind to its accepted named options. */
export type DatafnFieldOptionsByType = {
  string: DatafnStringFieldOptions;
  number: DatafnNumberFieldOptions;
  boolean: DatafnBooleanFieldOptions;
  object: DatafnObjectFieldOptions;
  array: DatafnArrayFieldOptions;
  date: DatafnDateFieldOptions;
  file: DatafnFileFieldOptions;
  json: DatafnJsonFieldOptions;
};

type KeysOfUnion<Value> = Value extends Value ? keyof Value : never;

type BooleanOption<
  Options,
  Key extends "required" | "nullable",
> = Key extends keyof Options
  ? Options extends { readonly [Option in Key]-?: true }
    ? true
    : true extends Exclude<Options[Key], undefined>
      ? boolean
      : false
  : false;

type DefinedOption<Options, Key extends PropertyKey> = Key extends keyof Options
  ? [Exclude<Options[Key], undefined>] extends [never]
    ? Record<never, never>
    : undefined extends Options[Key]
      ? { readonly [Option in Key]?: Exclude<Options[Key], undefined> }
      : Options extends { readonly [Option in Key]-?: unknown }
        ? { readonly [Option in Key]: Options[Key] }
        : { readonly [Option in Key]?: Options[Key] }
  : Record<never, never>;

/** Plain field schema returned by a const-safe field builder. */
export type DatafnBuiltField<
  Name extends string,
  Type extends DatafnFieldType,
  Options extends DatafnFieldOptionsByType[Type],
> = Options extends DatafnFieldOptionsByType[Type]
  ? Omit<Options, "name" | "type" | "required" | "nullable" | "default"> &
      DefinedOption<Options, "default"> & {
        readonly name: Name;
        readonly type: Type;
        readonly required: BooleanOption<Options, "required">;
        readonly nullable: BooleanOption<Options, "nullable">;
      }
  : never;

function buildField<
  const Name extends string,
  Type extends DatafnFieldType,
  Options extends DatafnFieldOptionsByType[Type],
>(
  name: Name,
  type: Type,
  options?: Options,
): DatafnBuiltField<Name, Type, Options> {
  const values = { ...options } as Record<string, unknown>;
  if (values.default === undefined) {
    delete values.default;
  }
  return {
    ...values,
    name,
    type,
    required: values?.required ?? false,
    nullable: values?.nullable ?? false,
  } as DatafnBuiltField<Name, Type, Options>;
}

type DatafnFieldBuilder<
  Type extends DatafnFieldType,
  OptionsShape extends DatafnFieldOptionsByType[Type],
> = {
  <const Name extends string>(
    name: Name,
  ): DatafnBuiltField<Name, Type, NoFieldOptions>;
  // Infer the complete caller shape before validating it, so a weak options
  // constraint cannot discard unknown-only keys. Keep exported unions intact.
  <const Name extends string, const Options extends object>(
    name: Name,
    options: Options & ([Options] extends [OptionsShape]
      ? Record<Exclude<KeysOfUnion<Options>, KeysOfUnion<OptionsShape>>, never>
      : never),
  ): DatafnBuiltField<Name, Type, Extract<Options, OptionsShape>>;
};

function createFieldBuilder<
  Type extends DatafnFieldType,
  OptionsShape extends DatafnFieldOptionsByType[Type],
>(type: Type): DatafnFieldBuilder<Type, OptionsShape> {
  return ((name: string, options?: OptionsShape) =>
    buildField(name, type, options)) as DatafnFieldBuilder<Type, OptionsShape>;
}

/**
 * Const-safe field builders. Each builder returns a plain schema object,
 * preserves inference-relevant literals, and defaults `required` and
 * `nullable` to `false`.
 */
export const field = {
  string: createFieldBuilder<"string", DatafnStringFieldOptions>("string"),
  number: createFieldBuilder<"number", DatafnNumberFieldOptions>("number"),
  boolean: createFieldBuilder<"boolean", DatafnBooleanFieldOptions>("boolean"),
  object: createFieldBuilder<"object", DatafnObjectFieldOptions>("object"),
  array: createFieldBuilder<"array", DatafnArrayFieldOptions>("array"),
  date: createFieldBuilder<"date", DatafnDateFieldOptions>("date"),
  file: createFieldBuilder<"file", DatafnFileFieldOptions>("file"),
  json: createFieldBuilder<"json", DatafnJsonFieldOptions>("json"),
} as const;
