export function toTemporalStorageValue(
  ms: number,
  storage: DatafnTemporalStorage = "unix-ms",
): number | string | Date {
  if (storage === "unix-s") {
    return Math.floor(ms / 1000);
  }
  if (storage === "date") {
    return new Date(ms);
  }
  if (storage === "iso") {
    return new Date(ms).toISOString();
  }
  return ms;
