    },
    ownKeys(_target) {
      return [
        ...Reflect.ownKeys(realClient),
        "switchContext",
        "currentNamespace",
        "subscribeClient",
      ];
    },
    getOwnPropertyDescriptor(_target, prop) {
      if (
        prop === "switchContext" ||
        prop === "currentNamespace" ||
        prop === "subscribeClient"
      ) {
        return {
          configurable: true,
          enumerable: true,
          writable: true,
          value: undefined,
        };
      }
      return Object.getOwnPropertyDescriptor(realClient, prop);
    },
  }) as DatafnClient<S>;

  return outer;
}
