import type { DatafnEvent } from "@datafn/core";

export interface EventFilter {
  type?: string | string[];
  resource?: string | string[];
  ids?: string | string[];
  mutationId?: string | string[];
  action?: string | string[]; // CLIENT-FILTER-001
  fields?: string | string[]; // CLIENT-FILTER-001
