    if (this.disposed) return;
    const next = { ...this.status, ...partial };
    if (isSameDatafnSyncStatus(this.status, next)) return;
    this.status = next;
    const snapshot = this.getStatus();
    this.subscribers.forEach((subscriber) => subscriber(snapshot));
