        retryable: false,
      },
    });
    resetWorkspaceDatafnClients.mockRejectedValue(new Error("teardown failed"));

    await expect(signOut()).rejects.toBeInstanceOf(AuthClientError);
    consoleError.mockRestore();
  });
});

